const proxied = new Proxy(service, {
  get(target, prop, receiver) {
    const value = Reflect.get(target, prop, receiver);   // unchanged behaviour
    if (typeof value !== 'function') return value;
    return (...args) => {
      const started = performance.now();
      try { return value.apply(target, args); }          // same contract
      finally { metrics.observe(prop, performance.now() - started); }
    };
  },
});

